ALTER TABLE "menu_item" ADD COLUMN IF NOT EXISTS "prices" jsonb DEFAULT '[]'::jsonb NOT NULL;--> statement-breakpoint
UPDATE "menu_item" AS i SET "prices" = jsonb_build_array(jsonb_build_object('label', '{"he": "צ׳ייסר", "en": "Chaser"}'::jsonb, 'amount', v.chaser, 'isVisible', true), jsonb_build_object('label', '{"he": "שוט", "en": "Shot"}'::jsonb, 'amount', v.shot, 'isVisible', true), jsonb_build_object('label', '{"he": "בקבוק", "en": "Bottle"}'::jsonb, 'amount', v.bottle, 'isVisible', true)) FROM (VALUES ('ערק', 19, 29, 200), ('סטוליצ׳ניה', 19, 29, 300), ('ג׳יימסון', 25, 41, 430), ('קמפרי', 25, 41, 360), ('ג׳ין בומביי', 25, 41, 520), ('ג׳ק דניאלס', 28, 44, 490)) AS v(name, chaser, shot, bottle) WHERE i."name"->>'he' = v.name AND i."amount" = v.chaser AND i."prices" = '[]'::jsonb;--> statement-breakpoint
UPDATE "menu_item" SET "description" = '{"he": "", "en": ""}'::jsonb WHERE "description"->>'he' = 'שוט / בקבוק / צ׳ייסר';--> statement-breakpoint
UPDATE "menu_item" SET "prices" = jsonb_build_array(jsonb_build_object('label', '{"he": "", "en": ""}'::jsonb, 'amount', "amount", 'isVisible', true)) WHERE "amount" IS NOT NULL AND "prices" = '[]'::jsonb;
